require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_admin();
$items=db()->query("SELECT p.*,l.title,u.name seller FROM fraud_predictions p JOIN listings l ON l.id=p.listing_id JOIN users u ON u.id=l.user_id ORDER BY p.created_at DESC LIMIT 200")->fetchAll();$pageTitle='ML Logs';include dirname(__DIR__).'/includes/header.php';?><div class="section-head"><div><h2>ML prediction logs</h2><p>Latest explainable fraud-analysis records.</p></div></div><div class="table-wrap"><table class="table"><tr><th>Listing</th><th>Seller</th><th>Score</th><th>Model</th><th>Signals</th><th>Date</th></tr><?php foreach($items as $p):?><tr><td><a href="/listing.php?id=<?=$p['listing_id']?>"><?=e($p['title'])?></a></td><td><?=e($p['seller'])?></td><td><?=e((string)$p['fraud_score'])?></td><td><?=e($p['model_name'])?> <?=e($p['model_version'])?></td><td>I <?=round((float)$p['image_score'])?> · P <?=round((float)$p['price_score'])?> · S <?=round((float)$p['seller_score'])?> · T <?=round((float)$p['text_score'])?> · Policy <?=round((float)$p['policy_score'])?></td><td><?=e($p['created_at'])?></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/includes/footer.php';?>